pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address admin = address(this);
        address nonAdmin = address(0x1234);

        c.setOwner(nonAdmin);

        vm.prank(nonAdmin);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", admin));

        assertTrue(!ok, "Only admin should be able to call setOwner");
    }
}
